<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';require_role('admin');$pdo=db();
$pledges=$pdo->query("SELECT dp.*,u.name donor_name,cr.title,c.organization_name,COALESCE(SUM(di.quantity),0) quantity FROM donation_pledges dp JOIN users u ON u.id=dp.donor_id JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id LEFT JOIN donation_items di ON di.pledge_id=dp.id GROUP BY dp.id ORDER BY dp.created_at DESC LIMIT 100")->fetchAll();$appointments=$pdo->query("SELECT a.*,u.name donor_name,cr.title,c.organization_name FROM appointments a JOIN donation_pledges dp ON dp.id=a.pledge_id JOIN users u ON u.id=dp.donor_id JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id ORDER BY a.appointment_date DESC,a.time_slot DESC LIMIT 100")->fetchAll();$pageTitle='Pledges & appointments';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">System-wide visibility</span><h1>Pledges & appointments</h1><p>Read-only oversight of community donations and handovers.</p></div><a class="button button-outline" href="<?=e(url('admin/dashboard.php'))?>">Admin overview</a></div><div class="panel"><div class="panel-heading"><h2>Donation pledges</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Donor</th><th>Charity & request</th><th>Items</th><th>Created</th><th>Status</th></tr></thead><tbody><?php foreach($pledges as $p):?><tr><td><?=e($p['donor_name'])?></td><td><strong><?=e($p['title'])?></strong><br><span class="muted"><?=e($p['organization_name'])?></span></td><td><?=$p['quantity']?></td><td><?=format_date($p['created_at'])?></td><td><span class="status <?=e(status_class($p['status']))?>"><?=e($p['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div><div class="panel" id="appointments" style="margin-top:22px"><div class="panel-heading"><h2>Drop-off appointments</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Donor</th><th>Request</th><th>Charity</th><th>Status</th></tr></thead><tbody><?php foreach($appointments as $a):?><tr><td><?=format_date($a['appointment_date'])?><br><span class="muted"><?=e(substr($a['time_slot'],0,5))?></span></td><td><?=e($a['donor_name'])?></td><td><?=e($a['title'])?></td><td><?=e($a['organization_name'])?></td><td><span class="status <?=e(status_class($a['status']))?>"><?=e($a['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
